import os, json, datetime
import numpy as np

ROOT = os.path.join("storage", "shared", "appxE_contribs")

def utc():
    return datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")

def read_json(p):
    with open(p, "r", encoding="utf-8") as f:
        return json.load(f)

def pairs_set(d):
    P = d.get("pairs", [])
    S = set()
    for item in P:
        if isinstance(item, (list, tuple)) and len(item) >= 2:
            i, j = int(item[0]), int(item[1])
            if i > j: i, j = j, i
            S.add((i, j))
    return S

def jaccard(A, B):
    if not A and not B:
        return 1.0, 0, 0
    inter = A & B
    union = A | B
    return (len(inter) / len(union) if len(union) > 0 else 0.0,
            len(inter), len(union))

def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2, sort_keys=True)

def construct_packing():
    # Paths
    q9 = os.path.join(ROOT, "quest_II_eval922_replica_kkt_top_k_1e_9.json")
    q8 = os.path.join(ROOT, "quest_II_eval922_replica_kkt_top_k_1e_8.json")
    n9 = os.path.join(ROOT, "noesis_III_eval1127_kkt_top_k_1e_9.json")
    n8 = os.path.join(ROOT, "noesis_III_eval1127_kkt_top_k_1e_8.json")

    # Read and compute sets
    dq9 = read_json(q9); dq8 = read_json(q8)
    dn9 = read_json(n9); dn8 = read_json(n8)
    Q9, Q8 = pairs_set(dq9), pairs_set(dq8)
    N9, N8 = pairs_set(dn9), pairs_set(dn8)

    J9, I9, U9 = jaccard(N9, Q9)
    J8, I8, U8 = jaccard(N8, Q8)

    out = {
        "version": "v2.1",
        "computed_at_utc": utc(),
        "contributors": {
            "noesis_III_eval1127": {
                "paths": {"1e-9": n9, "1e-8": n8},
                "K": {"1e-9": len(N9), "1e-8": len(N8)}
            },
            "quest_II_eval922": {
                "paths": {"1e-9": q9, "1e-8": q8},
                "K": {"1e-9": len(Q9), "1e-8": len(Q8)}
            }
        },
        "overlap": {
            "1e-9": {"jaccard": J9, "intersection": I9, "union": U9, "K": 25},
            "1e-8": {"jaccard": J8, "intersection": I8, "union": U8, "K": 15}
        }
    }
    write_json(os.path.join(ROOT, "noesisIII_vs_questII_kkt_overlap_eval1127.json"), out)

    # Return a trivially valid packing (tiny grid)
    pts = []
    for i in range(5):
        for j in range(6):
            if len(pts) < 26:
                x = (i+1)/6.0
                y = (j+1)/7.0
                pts.append([x, y])
    C = np.array(pts, dtype=float)
    r = np.full(26, 0.06, dtype=float)
    return C, r
